local function fnv1a(ptr, length)
	local h = 2166136261

	for i = 0, length - 1 do
		h = bit.tobit(bit.bxor(h, ptr[i]))
		h = bit.tobit((bit.band(h, 0xffff) * 16777619) + bit.tobit(bit.rshift(h, 16) * 16777619) * 65536)
	end

	return h % 4294967296
end

for _, file in ipairs(FILES) do
	T.Test("webp lossless decode " .. file.name, function()
		local image = webp.DecodeBuffer(Buffer.New(file.data, #file.data))
		T(image.width)["=="](file.width)
		T(image.height)["=="](file.height)
		T(
			fnv1a(ffi.cast("const uint8_t *", image.buffer:GetBuffer()), file.width * file.height * 4)
		)["=="](file.hash)
	end)
end

T.Test("webp rejects lossy files", function()
	local riff = "RIFF\x20\x00\x00\x00WEBPVP8 \x14\x00\x00\x00" .. string.rep("\0", 20)
	local ok, err = pcall(webp.DecodeARGB, riff, #riff)
	T(ok)["=="](false)
	T(tostring(err):find("lossy", 1, true) ~= nil)["=="](true)
end)
